<template>
  <div class="min-w-0 space-y-4" data-testid="archive-credentials">
    <div class="flex flex-wrap items-center justify-between gap-2 text-sm"><p>{{ state?.store.ready ? t('storageGov.credentialVault.ready') : t('storageGov.credentialVault.unavailable') }}<span v-if="state?.store.ready"> · v{{ state.store.revision }}</span></p><UButton color="neutral" variant="ghost" :loading="busy" :disabled="!!unknown" @click="load">{{ t('storageGov.refresh') }}</UButton></div>
    <UAlert v-if="error" color="error" :title="t('storageGov.requestFailed')" :description="error" />
    <UAlert v-if="!state?.store.ready" color="warning" :title="t('storageGov.credentialVault.unavailable')" :description="t('storageGov.credentialVault.setup')" />
    <UAlert v-if="state?.store.rotation_required" color="warning" :title="t('storageGov.credentialVault.rotationRequired')" :description="t('storageGov.credentialVault.rotationHint')" />
    <div v-if="unknown" class="space-y-3" data-testid="credential-unknown"><UAlert color="warning" :title="t('storageGov.tableMonitor.control.unknown')" :description="t('storageGov.tableMonitor.control.unknownHint')" /><UButton :loading="busy" data-testid="credential-reconcile" @click="reconcile">{{ t('storageGov.tableMonitor.control.reconcile') }}</UButton></div>
    <p v-if="notice" class="text-sm text-success" role="status">{{ notice }}</p>
    <BackupSectionTabs v-model="section" :items="sections" :label="t('storageGov.credentialVault.title')">
      <template #list>
        <div class="space-y-4">
          <div class="flex flex-wrap gap-2"><UButton :disabled="busy || !!unknown || !state?.store.ready || state.store.rotation_required" data-testid="credential-new" @click="edit()">{{ t('storageGov.archive.newCredential') }}</UButton><UButton v-if="state?.store.rotation_required" color="neutral" variant="outline" :disabled="busy || !!unknown" data-testid="credential-rewrap" @click="candidate = {action:'rewrap'}">{{ t('storageGov.credentialVault.rotateKey') }}</UButton></div>
          <div class="overflow-x-auto rounded-lg border border-default"><table class="block w-full text-left text-sm sm:table"><thead class="hidden bg-elevated sm:table-header-group"><tr><th class="p-3">{{ t('storageGov.archive.credential') }}</th><th class="p-3">{{ t('storageGov.credentialVault.status') }}</th><th class="p-3">{{ t('storageGov.credentialVault.version') }}</th><th class="p-3">{{ t('storageGov.credentialVault.actions') }}</th></tr></thead><tbody class="block sm:table-row-group"><tr v-if="!state?.items.length"><td colspan="4" class="p-4 text-muted">{{ t(state?.store.ready ? 'storageGov.credentialVault.empty' : 'storageGov.credentialVault.unavailable') }}</td></tr><tr v-for="row in state?.items || []" :key="row.ref" class="grid grid-cols-2 items-start border-t border-default sm:table-row" :data-credential-ref="row.ref"><td class="col-span-2 break-all px-3 pt-3 font-medium sm:p-3">{{ row.ref }}</td><td class="p-3"><p class="mb-1 text-xs text-muted sm:hidden">{{ t('storageGov.credentialVault.status') }}</p>{{ t('storageGov.credentialVault.states.' + row.state) }}</td><td class="p-3 tabular-nums"><p class="mb-1 text-xs text-muted sm:hidden">{{ t('storageGov.credentialVault.version') }}</p>v{{ row.revision }}<p class="text-xs text-muted">{{ t('storageGov.credentialVault.origins.' + row.origin) }}</p></td><td class="col-span-2 px-3 pb-3 sm:p-3"><div class="flex flex-wrap gap-2"><UButton v-if="row.origin === 'legacy' && row.state !== 'recovery_required'" size="sm" color="neutral" variant="outline" :disabled="blocked" data-testid="credential-adopt" @click="candidate={action:'adopt',row}">{{ t('storageGov.credentialVault.adopt') }}</UButton><template v-else><UButton size="sm" color="neutral" variant="outline" :disabled="blocked" data-testid="credential-edit" @click="edit(row)">{{ t('storageGov.credentialVault.replace') }}</UButton><UButton v-if="row.origin === 'sealed' && ['active', 'recovery_required'].includes(row.state)" size="sm" color="error" variant="outline" :disabled="blocked" data-testid="credential-revoke" @click="candidate={action:'revoke',row}">{{ t('storageGov.credentialVault.revoke') }}</UButton></template></div></td></tr></tbody></table></div>
        </div>
      </template>
      <template #editor>
        <UForm :schema="schema" :state="form" class="space-y-4" data-testid="credential-form" @submit="save">
          <p class="text-sm text-muted">{{ t('storageGov.credentialVault.editorHint') }}</p>
          <UFormField name="ref" :label="t('storageGov.archive.credential')"><UInput v-model="form.ref" :disabled="blocked || editing" autocomplete="off" class="w-full" data-testid="credential-ref" /></UFormField>
          <p v-if="editing" class="text-sm text-muted">{{ t('storageGov.credentialVault.version') }} v{{ baseRevision }}</p>
          <UFormField name="access_key" label="Access Key"><UInput v-model="form.access_key" :disabled="blocked" type="password" autocomplete="new-password" class="w-full" data-testid="credential-access" /></UFormField>
          <UFormField name="secret_key" label="Secret Key"><UInput v-model="form.secret_key" :disabled="blocked" type="password" autocomplete="new-password" class="w-full" data-testid="credential-secret" /></UFormField>
          <UFormField name="session_token" :label="t('storageGov.archive.sessionToken')"><UInput v-model="form.session_token" :disabled="blocked" type="password" autocomplete="new-password" class="w-full" /></UFormField>
          <UButton type="submit" :loading="busy" :disabled="blocked" data-testid="credential-save">{{ t('storageGov.credentialVault.save') }}</UButton>
        </UForm>
      </template>
    </BackupSectionTabs>
    <UModal :open="!!candidate" :title="t('storageGov.credentialVault.confirmTitle')" :description="t('storageGov.credentialVault.confirmHint')" :dismissible="!busy && !unknown" :close="busy || unknown ? false : undefined" @update:open="value => {if (!value) candidate=undefined}"><template #body><div class="space-y-4"><p class="break-all text-sm">{{ candidate?.row?.ref || t('storageGov.credentialVault.rotateKey') }}</p><p class="text-sm">{{ t('storageGov.credentialVault.confirmActions.' + (candidate?.action || 'adopt')) }}</p><UButton color="warning" :loading="busy" :disabled="!!unknown" data-testid="credential-control-confirm" @click="control">{{ t('storageGov.credentialVault.confirm') }}</UButton></div></template></UModal>
  </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import * as v from 'valibot';
import BackupSectionTabs from './BackupSectionTabs.vue';
import { useArchiveOpsService, type ArchiveCredentialView, type ArchiveCredentialOverview, type ArchiveCredentialMutation } from '~/composables/api/services/archiveOpsService';
const props=defineProps<{revision?:number}>(),emit=defineEmits<{busy:[boolean];changed:[]}>(),{t}=useI18n(),api=useArchiveOpsService();
const state=ref<ArchiveCredentialOverview>(),busy=ref(false),error=ref(''),notice=ref(''),section=ref('list'),editing=ref(false),baseRevision=ref(0);
const candidate=ref<{action:'adopt'|'revoke'|'rewrap';row?:ArchiveCredentialView}>();
type Operation={key:string;action:'save'|'adopt'|'revoke'|'rewrap';ref:string;revision:number};
const unknown=ref<Operation>(),form=reactive({ref:'',access_key:'',secret_key:'',session_token:''});let controller:AbortController|undefined,readController:AbortController|undefined;
const sections=computed(()=>[{value:'list',label:t('storageGov.credentialVault.list')},{value:'editor',label:t('storageGov.credentialVault.editor')}]);
const blocked=computed(()=>busy.value||!!unknown.value||!state.value?.store.ready||!!state.value.store.rotation_required);
const required=v.pipe(v.string(),v.minLength(1));const schema=v.object({ref:v.pipe(required,v.regex(/^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/)),access_key:v.pipe(required,v.maxLength(256)),secret_key:v.pipe(required,v.maxLength(1024)),session_token:v.pipe(v.string(),v.maxLength(16384))});
function erase(){Object.assign(form,{access_key:'',secret_key:'',session_token:''});}
async function load(){readController?.abort();const c=readController=new AbortController();try{const value=await api.credentialOverview(c.signal);if(!c.signal.aborted)state.value=value}catch(e){if(!c.signal.aborted)error.value=e instanceof Error?e.message:t('storageGov.requestFailed')}}
function edit(row?:ArchiveCredentialView){if(blocked.value)return;erase();editing.value=!!row;form.ref=row?.ref||'';baseRevision.value=row?.origin === 'sealed' ? row.revision : 0;section.value='editor';notice.value='';error.value='';}
function accepted(result:ArchiveCredentialMutation,op:Operation){const r=result.receipt;if(r.request_id!==op.key||r.action!==op.action||(r.ref||'')!==op.ref||(op.action!=='rewrap'&&r.revision!==op.revision+1)||(op.action==='rewrap'&&r.store_revision!==op.revision+1))throw new Error('ARCHIVE_CREDENTIAL_RESPONSE_INVALID');state.value=result.overview;unknown.value=undefined;candidate.value=undefined;notice.value=t('storageGov.credentialVault.saved');if(op.action==='save'){erase();section.value='list'}emit('changed');}
async function write(op:Operation,call:(signal:AbortSignal)=>Promise<ArchiveCredentialMutation>){if(busy.value||unknown.value)return;const c=controller=new AbortController();busy.value=true;error.value='';notice.value='';try{const result=await call(c.signal);if(!c.signal.aborted)accepted(result,op)}catch(e:any){if(!c.signal.aborted){const status=e?.statusCode||e?.status||e?.response?.status;if(![400,401,403,404,409,422,428].includes(status))unknown.value=op;error.value=e instanceof Error?e.message:t('storageGov.requestFailed')}}finally{erase();candidate.value=undefined;if(!c.signal.aborted)busy.value=false}}
async function save(){if(blocked.value||!v.safeParse(schema,form).success)return;const op:Operation={key:crypto.randomUUID(),action:'save',ref:form.ref,revision:baseRevision.value};const input={...form,request_id:op.key,expected_revision:op.revision};await write(op,signal=>api.saveCredential(input,signal));}
async function control(){const c=candidate.value;if(!c||busy.value||unknown.value)return;const op:Operation={key:crypto.randomUUID(),action:c.action,ref:c.row?.ref||'',revision:c.action==='rewrap'?state.value?.store.revision||0:c.action==='adopt'?0:c.row?.revision||0};const input={request_id:op.key,expected_revision:c.action==='adopt'?c.row!.revision:op.revision,legacy_digest:c.action==='adopt'?c.row!.legacy_digest:undefined,confirm:true as const};await write(op,signal=>c.action==='rewrap'?api.rotateCredentialKey(input,signal):api.controlCredential(c.action==='adopt'?'adoptions':'revocations',op.ref,input,signal));}
async function reconcile(){const op=unknown.value;if(!op||busy.value)return;const c=controller=new AbortController();busy.value=true;try{const result=await api.credentialRequest(op.key,c.signal);if(!c.signal.aborted){accepted(result,op);error.value=''}}catch(e){if(!c.signal.aborted)error.value=e instanceof Error?e.message:t('storageGov.requestFailed')}finally{if(!c.signal.aborted)busy.value=false}}
watch(()=>busy.value||!!unknown.value,value=>emit('busy',value));watch(()=>props.revision,load);onMounted(load);onBeforeUnmount(()=>{controller?.abort();readController?.abort();erase();emit('busy',false)});
</script>
